import { test, expect, Page } from '@playwright/test';

test.describe('Product Image Pinch-to-Zoom', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('https://example.com/product');
    await page.waitForLoadState('networkidle');
  });

  test('should zoom in on product image with pinch gesture', async () => {
    const productImage = page.getByRole('img', { name: /product image/i });

    // Get initial image dimensions
    const initialBoundingBox = await productImage.boundingBox();
    expect(initialBoundingBox).not.toBeNull();
    const initialWidth = initialBoundingBox!.width;
    const initialHeight = initialBoundingBox!.height;

    // Simulate pinch-to-zoom gesture
    const centerX = initialBoundingBox!.x + initialWidth / 2;
    const centerY = initialBoundingBox!.y + initialHeight / 2;

    // Simulate two-finger touch start
    await page.touchscreen.tap(centerX - 20, centerY - 20);
    await page.touchscreen.tap(centerX + 20, centerY + 20);

    // Move fingers apart to simulate pinch zoom in
    await page.evaluate(() => {
      const touchEvent = new TouchEvent('touchmove', {
        bubbles: true,
        cancelable: true,
        touches: [
          new Touch({
            identifier: 0,
            target: document.querySelector('img') as EventTarget,
            clientX: window.innerWidth / 2 - 40,
            clientY: window.innerHeight / 2 - 40,
            screenX: window.innerWidth / 2 - 40,
            screenY: window.innerHeight / 2 - 40,
            pageX: window.innerWidth / 2 - 40,
            pageY: window.innerHeight / 2 - 40,
            radiusX: 2.5,
            radiusY: 2.5,
            rotationAngle: 0,
            force: 1,
          }),
          new Touch({
            identifier: 1,
            target: document.querySelector('img') as EventTarget,
            clientX: window.innerWidth / 2 + 40,
            clientY: window.innerHeight / 2 + 40,
            screenX: window.innerWidth / 2 + 40,
            screenY: window.innerHeight / 2 + 40,
            pageX: window.innerWidth / 2 + 40,
            pageY: window.innerHeight / 2 + 40,
            radiusX: 2.5,
            radiusY: 2.5,
            rotationAngle: 0,
            force: 1,
          }),
        ] as any,
      });
      document.querySelector('img')?.dispatchEvent(touchEvent);
    });

    // Wait for zoom animation to complete
    await page.waitForTimeout(500);

    // Verify image has been zoomed
    const zoomedBoundingBox = await productImage.boundingBox();
    expect(zoomedBoundingBox).not.toBeNull();

    // Check that the image appears larger (transform scale applied)
    const hasZoomClass = await productImage.evaluate((el) => {
      const transform = window.getComputedStyle(el).transform;
      return transform !== 'none' && transform.includes('scale');
    });

    expect(hasZoomClass).toBeTruthy();
  });

