            screenX: window.innerWidth / 2 + 10,
            screenY: window.innerHeight / 2 + 10,
            pageX: window.innerWidth / 2 + 10,
            pageY: window.innerHeight / 2 + 10,
            radiusX: 2.5,
            radiusY: 2.5,
            rotationAngle: 0,
            force: 1,
          }),
        ] as any,
      });
      document.querySelector('img')?.dispatchEvent(touchEvent);
    });

    await page.waitForTimeout(500);

    // Verify image zoom level has changed
    const currentScale = await productImage.evaluate((el) => {
      const transform = window.getComputedStyle(el).transform;
      const match = transform.match(/scale\(([^)]+)\)/);
      return match ? parseFloat(match[1]) : 1;
    });

    expect(currentScale).toBeLessThan(2);
  });

  test('should maintain image aspect ratio during zoom', async () => {
    const productImage = page.getByRole('img', { name: /product image/i });

    const initialAspectRatio = await productImage.evaluate((el) => {
