      return rect.width / rect.height;
    });

    // Apply zoom
    await page.evaluate(() => {
      const img = document.querySelector('img') as HTMLElement;
      if (img) {
        img.style.transform = 'scale(1.5)';
      }
    });

    await page.waitForTimeout(300);

    const zoomedAspectRatio = await productImage.evaluate((el) => {
      const rect = el.getBoundingClientRect();
      return rect.width / rect.height;
    });

    // Aspect ratio should remain the same
    expect(Math.abs(initialAspectRatio - zoomedAspectRatio)).toBeLessThan(0.01);
  });

